children.dataScript:
(function() {
  var actor = BattleManager.actor();
  if (!actor) return [];
  var cmds = [{
    name: TextManager.attack,
    symbol: "attack",
    enabled: actor.canAttack(),
    iconIndex: 76
  }];
  actor.addedSkillTypes().sort(function(a, b) {
    return a - b;
  }).forEach(function(id) {
    cmds.push({
      name: $dataSystem.skillTypes[id] || '',
      symbol: "skill",
      enabled: true,
      ext: id,
      iconIndex: 79
    });
  });
  cmds.push({
    name: TextManager.guard,
    symbol: "guard",
    enabled: actor.canGuard(),
    iconIndex: 81
  }, {
    name: TextManager.item,
    symbol: "item",
    enabled: true,
    iconIndex: 83
  });
  return cmds;
})()
